-- exmd9-2.hs: extended Minsky doubling (value x9, 2 cycles)
-- Start: (0, 0, 0). Goal: (0, 0, 1). The value reaches 9^2 = 81.
-- Generated by make-exmd.py.  Feed through hs2maze.py to obtain the maze.

exmd :: (Int, Int, Int) -> (Int, Int, Int)

-- Phase 0 (pc=0): y := 1
exmd (x, y,    0) = exmd (  x, y+1,    2)

-- Cycle 0 (pc=2): y -> x, x9
exmd (x, 0,    2) = exmd (  x,   0,   12)
exmd (x, y,    2) = exmd (  x, y-1,    3)
exmd (x, y,    3) = exmd (x+1,   y,    4)
exmd (x, y,    4) = exmd (x+1,   y,    5)
exmd (x, y,    5) = exmd (x+1,   y,    6)
exmd (x, y,    6) = exmd (x+1,   y,    7)
exmd (x, y,    7) = exmd (x+1,   y,    8)
exmd (x, y,    8) = exmd (x+1,   y,    9)
exmd (x, y,    9) = exmd (x+1,   y,   10)
exmd (x, y,   10) = exmd (x+1,   y,   11)
exmd (x, y,   11) = exmd (x+1,   y,    2)

-- Cycle 1 (pc=12): x -> y, x9
exmd (0, y,   12) = exmd (  0,   y,   22)
exmd (x, y,   12) = exmd (x-1,   y,   13)
exmd (x, y,   13) = exmd (  x, y+1,   14)
exmd (x, y,   14) = exmd (  x, y+1,   15)
exmd (x, y,   15) = exmd (  x, y+1,   16)
exmd (x, y,   16) = exmd (  x, y+1,   17)
exmd (x, y,   17) = exmd (  x, y+1,   18)
exmd (x, y,   18) = exmd (  x, y+1,   19)
exmd (x, y,   19) = exmd (  x, y+1,   20)
exmd (x, y,   20) = exmd (  x, y+1,   21)
exmd (x, y,   21) = exmd (  x, y+1,   12)

-- Drain (pc=22): DEC y to 0, then HALT
exmd (x, 0,   22) = (  x,   0,    1)
exmd (x, y,   22) = exmd (  x, y-1,   22)
